package com.fit.badminton.member; import com.fit.badminton.member.dto.*; import com.fit.badminton.storage.*; import jakarta.validation.Valid; import java.io.IOException; import java.util.List; import org.springframework.http.MediaType; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile;
@RestController @RequestMapping("/api/admin/members")
public class MemberController {private final MemberService service;private final QrStorageService storage; public MemberController(MemberService s,QrStorageService q){service=s;storage=q;}
 @GetMapping public List<MemberResponse> list(@RequestParam(defaultValue="false") boolean activeOnly){return service.list(activeOnly);} @GetMapping("/{id}") public MemberResponse get(@PathVariable long id){return service.get(id);} @PostMapping public MemberResponse create(@Valid @RequestBody MemberRequest r){return service.create(r);} @PutMapping("/{id}") public MemberResponse update(@PathVariable long id,@Valid @RequestBody MemberRequest r){return service.update(id,r);}
 @PostMapping(value="/{id}/qr",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) public MemberResponse qr(@PathVariable long id,@RequestPart("file") MultipartFile file) throws IOException {if(file.getSize()>2_000_000)throw new IllegalArgumentException("QR image must be 2 MB or smaller");String ct=file.getContentType();if(ct==null||!(ct.equals("image/png")||ct.equals("image/jpeg")||ct.equals("image/webp")))throw new IllegalArgumentException("QR must be PNG, JPEG or WebP");String path=storage.upload(id,file.getBytes(),ct);service.updateQrPath(id,path);return service.get(id);}
}
